{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/activity-feed.json
    A panel with recent events: a timeline with dots on a line, or a list of rows with an icon. Axes: layout (timeline, list), density (default, compact), tone (default, muted).
    Props (p): id, title, text, events, layout, density, tone, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_text = ($p['text'] ?? null)}
{var $v_events = ($p['events'] ?? null)}
{var $v_layout = ($p['layout'] ?? 'timeline')}
{var $v_density = ($p['density'] ?? 'default')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $c_9}
  {capture $c_8}
    {capture $c_7}
      {if ui_t(ui_eq($v_layout, 'timeline'))}
        {=ui_include('blocks/timeline.latte', ['p' => ['items' => $v_events]])|noescape}
      {else}
        {capture $c_6}
          {foreach ui_l($v_events) as $v_e}
            {capture $c_5}
              {capture $c_3}
                {capture $c_1}
                  {=ui_text(ui_get($v_e, ['title']))}
                {/capture}
                {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Weight' => 'semibold'], 'children' => $c_1])|noescape}
                {if ui_t(ui_eq($v_density, 'default'))}
                  {capture $c_2}
                    {=ui_text(ui_get($v_e, ['text']))}
                  {/capture}
                  {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Class' => 'text-muted-foreground'], 'children' => $c_2])|noescape}
                {/if}
              {/capture}
              {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '0'], 'children' => $c_3])|noescape}
              {capture $c_4}
                {=ui_text(ui_get($v_e, ['time']))}
              {/capture}
              {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'xs', 'Class' => 'shrink-0 text-muted-foreground'], 'children' => $c_4])|noescape}
            {/capture}
            {=ui_include('ui/list/list-item.latte', ['p' => ['Class' => ui_s(ui_cnv(['flex items-start justify-between gap-4 border-b border-border last:border-0', (ui_t(ui_eq($v_density, 'compact')) ? 'py-2' : 'py-4')])), 'Attrs' => ui_attrs(['data-testid', 'item'])], 'children' => $c_5])|noescape}
          {/foreach}
        {/capture}
        {=ui_include('ui/list/list.latte', ['p' => ['Class' => 'm-0 flex list-none flex-col p-0', 'Attrs' => ui_attrs(['data-testid', 'items'])], 'children' => $c_6])|noescape}
      {/if}
    {/capture}
    {=ui_include('blocks/panel.latte', ['p' => ['title' => $v_title, 'description' => $v_text, 'id' => $v_id, 'className' => ui_cnv([(ui_t(ui_eq($v_tone, 'muted')) ? 'bg-muted' : '')])], 'children' => $c_7])|noescape}
  {/capture}
  {=ui_include('ui/container/container.latte', ['p' => ['Class' => 'mx-auto w-full max-w-6xl px-4 py-8', 'Attrs' => ui_attrs(['data-slot', 'container'])], 'children' => $c_8])|noescape}
{/capture}
{=ui_include('ui/block/block.latte', ['p' => ['Tag' => 'section', 'Attrs' => ui_attrs(['aria-labelledby', (ui_t($v_landmarkLabel) ? null : (ui_t(ui_and([$v_title, $v_id])) ? ui_tpl('{0}-t', [$v_id]) : null)), 'data-testid', 'panel-section', 'aria-label', $v_landmarkLabel])], 'children' => $c_9])|noescape}
